<?php
/**
 * Shared HTML print document shell. Callers provide already-authorized,
 * normalized data and render only the fields appropriate to the document.
 */
$printDocument = $printDocument ?? [];
$printClinic = $printDocument['clinic'] ?? [];
$printPatient = $printDocument['patient'] ?? [];
$printMeta = $printDocument['metadata'] ?? [];
?>
<article class="rootins-print-document" data-print-document="<?= esc($printDocument['type'] ?? 'document', 'attr') ?>">
    <header class="rootins-print-header">
        <div class="rootins-print-brand"><img src="<?= base_url('assets/img/logo.png') ?>" alt="ROOTINS logo"><div><strong><?= esc($printClinic['clinic_name'] ?? 'ROOTINS Clinic') ?></strong><span><?= esc($printClinic['address'] ?? '') ?></span><span><?= esc(implode(' | ', array_filter([$printClinic['mobile'] ?? '', $printClinic['email'] ?? '']))) ?></span></div></div>
        <div class="rootins-print-title"><h1><?= esc($printDocument['title'] ?? 'Document') ?></h1><span><?= esc($printDocument['reference'] ?? '') ?></span></div>
    </header>
    <?php if ($printPatient !== []): ?><section class="rootins-print-section rootins-print-patient"><h2>Patient details</h2><dl><div><dt>Patient name</dt><dd><?= esc($printPatient['name'] ?? '') ?></dd></div><div><dt>Registration number</dt><dd><?= esc($printPatient['registration_number'] ?? '') ?></dd></div><div><dt>Mobile</dt><dd><?= esc($printPatient['mobile'] ?? '') ?></dd></div><?php if (! empty($printPatient['address'])): ?><div><dt>Address</dt><dd><?= esc($printPatient['address']) ?></dd></div><?php endif; ?></dl></section><?php endif; ?>
    <?php if ($printMeta !== []): ?><section class="rootins-print-section rootins-print-metadata"><h2>Document details</h2><dl><?php foreach ($printMeta as $label => $value): ?><?php if ((string) $value !== ''): ?><div><dt><?= esc(ucwords(str_replace('_', ' ', (string) $label))) ?></dt><dd><?= esc((string) $value) ?></dd></div><?php endif; ?><?php endforeach; ?></dl></section><?php endif; ?>
    <div class="rootins-print-content"><?= $printDocument['content'] ?? '' ?></div>
    <footer class="rootins-print-footer"><span>Generated by ROOTINS<?= ! empty($printDocument['generated_at']) ? ' on ' . esc($printDocument['generated_at']) : '' ?></span><span><?= esc($printDocument['footer'] ?? '') ?></span></footer>
</article>
